static __forceinline bool AllNear(const hkVector4& a, const hkVector4& b, float eps)
{
    hkVector4 t;
    t.x = a.x - b.x;
    t.y = a.y - b.y;
    t.z = a.z - b.z;
    t.w = a.w - b.w;
    t.x = hkAbs(t.x);
    t.y = hkAbs(t.y);
    t.z = hkAbs(t.z);
    t.w = hkAbs(t.w);
    int mx = t.x <= eps ? 8 : 0;
    int my = t.y <= eps ? 4 : 0;
    int mz = t.z <= eps ? 2 : 0;
    int mw = t.w <= eps ? 1 : 0;
    int mask = mx | my | mz | mw;
    return (mask & 0xf) == 0xf;
}

